    try { var response=await fetch('/app/configuracao-modos/'+savedMode+'/'+savedClass,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:data.revision,settings:data.modes[savedMode][savedClass]})}); var result=await response.json();if(!response.ok)throw new Error(typeof result.detail==='string'?result.detail:'Verifique os campos da configuração.');data.revision=result.revision;data.modes[savedMode][savedClass]=result.settings;status.textContent='Configuração '+(savedMode==='INI'?'Ini':'Nova')+' / '+data.classes[savedClass]+' salva. Gere o N3 para aplicar.'; }
    catch(error){status.textContent=error.message;}
    finally{busy=false;dialog.querySelectorAll('[role=tab]').forEach(function(button){button.disabled=false;});form.querySelector('[type=submit]').disabled=false;}
  });
}());

