.drawing-config-dialog { width:min(1080px,94vw); max-height:90vh; padding:22px; border:1px solid #93b4f5; border-radius:12px; color:#102442; background:#fff; }
.drawing-config-dialog::backdrop { background:rgba(5,16,35,.65); }
.drawing-config-head { display:flex; align-items:center; justify-content:space-between; gap:16px; }
.drawing-config-head h2 { margin:0; font-size:1.3rem; }
.drawing-config-head button { border:0; font-size:1.5rem; background:transparent; cursor:pointer; }
.drawing-config-dialog p { font-size:.85rem; }
#drawing-config-modes { grid-template-columns:repeat(2,minmax(0,1fr)); margin:16px 0 8px; }
#drawing-config-classes { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:6px; margin-bottom:16px; }
.drawing-config-section { border:1px solid #d4def0; border-radius:7px; margin:12px 0; padding:12px; }
.drawing-config-section legend { font-weight:600; padding:0 5px; }
.drawing-config-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.drawing-config-grid label { display:flex; flex-direction:column; gap:5px; font-size:.8rem; overflow-wrap:anywhere; }
.drawing-config-dialog input:not([type=checkbox]), .drawing-config-dialog select { width:100%; box-sizing:border-box; padding:7px; border:1px solid #b8c9e4; border-radius:4px; font:inherit; background:white; }
.drawing-config-dialog input[type=checkbox] { margin-right:6px; }
.drawing-config-layer { display:grid; grid-template-columns: minmax(100px,1fr) minmax(130px,1fr) 85px 70px; gap:10px; align-items:center; padding:5px 0; font-size:.8rem; }
.drawing-config-actions { position:sticky; bottom:-22px; background:white; border-top:1px solid #d4def0; padding:15px 0; display:flex; gap:15px; align-items:center; }
.drawing-config-legacy { font-size:.8rem; color:#52627a; }
.drawing-config-legacy table { width:100%; border-collapse:collapse; margin-top:10px; }
.drawing-config-legacy td { border-bottom:1px solid #e1e7f0; padding:5px; overflow-wrap:anywhere; }
@media(max-width:700px) { .drawing-config-grid { grid-template-columns:1fr; } #drawing-config-classes { grid-template-columns:repeat(2,1fr); } .drawing-config-layer { grid-template-columns:1fr 1fr 60px 50px; gap:5px; } }

